insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_11_v1'
from (values
('127.59.d.1.A',3,'A student maps soil samples from a school plot for a year as a GIS project and tracks the results. This is a:','["Supervised agricultural experience using GIS", "Fire drill", "Class photo", "Lunch schedule"]'::jsonb,0,'An SAE is a planned, supervised, hands-on project.','original'),
('127.59.d.1.A',4,'Which step comes last when running a GIS-based SAE?','["Starting without goals", "Evaluating the results against the plan", "Deleting the maps", "Skipping the plan"]'::jsonb,1,'Evaluation closes the cycle of plan, conduct and document.','original'),
('127.59.d.1.B',2,'Why log the date each field boundary was mapped in a GIS project?','["To hide errors", "To fill the page", "So the data can be traced and updated later", "To confuse readers"]'::jsonb,2,'Good records show when data were collected.','original'),
('127.59.d.1.B',3,'A solid GIS SAE record book would include:','["Game scores", "Only photos of friends", "Nothing", "Data sources, hours, and costs"]'::jsonb,3,'Records track the work and its results.','original'),
('127.59.d.1.C',2,'Which activity builds leadership in a GIS agriculture program?','["Leading a mapping demonstration for younger members", "Skipping meetings", "Staying silent", "Avoiding teamwork"]'::jsonb,0,'Leading others builds leadership skills.','original'),
('127.59.d.1.D',2,'A chapter''s program of activities for a GIS class could include:','["Hidden plans", "A field-mapping service project", "No events", "Cancelled meetings"]'::jsonb,1,'The program lists planned activities for the year.','original'),
('127.59.d.1.D',3,'A member who helps run the field-mapping service project is:','["Avoiding service", "Quitting the chapter", "Participating in the local program of activities", "Breaking chapter rules"]'::jsonb,2,'Taking part supports the chapter''s goals.','original'),
('127.59.d.1.E',3,'A résumé line listing ''built yield maps for a school farm'' is:','["A lab safety sign", "A school rule", "A weather report", "Documentation of relevant agricultural experience"]'::jsonb,3,'Documented experience supports job and scholarship applications.','original'),
('127.59.d.1.E',2,'Why keep documentation of GIS experience current?','["It supports applications for jobs and awards", "It prevents hiring", "It wastes time", "It hides skills"]'::jsonb,0,'Current records show real skills.','original'),
('127.59.d.2.A',3,'A career that uses GIS in agriculture is:','["Bus driver only", "Precision agriculture technician", "Lifeguard only", "Pastry chef only"]'::jsonb,1,'Precision ag specialists use spatial data to guide field decisions.','original'),
('127.59.d.2.A',4,'Emerging GIS careers in farming are growing because of:','["Fewer farms using data", "Paper-only records", "Drones, sensors, and data-driven management", "Less technology"]'::jsonb,2,'Technology creates new data jobs.','original'),
('127.59.d.2.B',3,'A farm uses GIS to map where fertilizer is applied. This is an application in:','["Fashion design", "Music mixing", "Movie editing", "Precision nutrient management"]'::jsonb,3,'GIS shows where inputs go and how much.','original'),
('127.59.d.2.B',4,'Food companies use GIS to track:','["Where crops are grown and how they move to market", "Only weather in space", "Only sports teams", "Only school bus routes"]'::jsonb,0,'Supply chains are mapped spatially.','original'),
('127.59.d.2.C',3,'GIS data in agriculture are typically tied to:','["A person''s mood", "A location on the earth", "No place", "A random number"]'::jsonb,1,'Spatial data have a geographic position.','original'),
('127.59.d.2.C',4,'A table of soil test results linked to field coordinates is an example of:','["Only audio", "Unrelated lists", "Attribute data connected to spatial data", "Only pictures"]'::jsonb,2,'Attributes describe features at locations.','original'),
('127.59.d.2.D',3,'A person using drones for crop scouting may need:','["A fishing permit", "A driver''s license only", "No credentials", "Pilot certification from the FAA"]'::jsonb,3,'Commercial drone flights require certification.','original'),
('127.59.d.2.D',4,'Credentialing in GIS can help workers to:','["Show verified skills to employers", "Avoid learning", "Reduce pay", "Skip training"]'::jsonb,0,'Certifications signal competence.','original'),
('127.59.d.3.A',2,'One use of GIS in agriculture is to:','["Cook meals", "Map field boundaries and soil types", "Write poems", "Paint barns"]'::jsonb,1,'GIS organizes location-based farm information.','original'),
('127.59.d.3.A',3,'GIS helps farmers decide where to apply water by showing:','["School schedules", "Only roads", "Areas that are dry or wet", "Their favorite color"]'::jsonb,2,'Maps of moisture guide irrigation.','original'),
('127.59.d.3.B',3,'In GIS, a ''layer'' is:','["A coat of paint", "A cake", "A wire", "A set of map data on one theme, such as soils"]'::jsonb,3,'Layers stack different themes.','original'),
('127.59.d.3.B',4,'The term for a feature stored as a point, line, or polygon is:','["Vector data", "Raster data", "Static", "Noise"]'::jsonb,0,'Vector features use coordinates.','original'),
('127.59.d.3.C',3,'A yield map made from combine data is a model that shows:','["Wind speed only", "How crop yield varies across a field", "The price of fuel", "The sky color"]'::jsonb,1,'Models represent patterns in the field.','original'),
('127.59.d.3.C',4,'Variable-rate application models use maps to:','["Ignore soil", "Apply the same amount everywhere", "Change input amounts across a field", "Stop planting"]'::jsonb,2,'Prescription maps guide equipment.','original'),
('127.59.d.3.D',4,'A soil survey map divides land into:','["Random shapes", "Equal circles", "City blocks", "Map units with similar soil properties"]'::jsonb,3,'Soil maps group similar soils.','original'),
('127.59.d.3.E',3,'Organizing yield-monitor data by field helps a farmer to:','["Plan which crops and inputs suit each area", "Skip harvest", "Ignore history", "Lose records"]'::jsonb,0,'Spatial data support planning.','original'),
('127.59.d.3.E',4,'If one corner of a field has low yield each year, spatial data may point to:','["A calendar error", "A soil or drainage problem there", "A broken printer", "A new logo"]'::jsonb,1,'Patterns suggest causes.','original'),
('127.59.d.3.F',3,'An ethical concern with farm GIS data is:','["The file name", "The font size", "Who owns and can see the data", "The color of icons"]'::jsonb,2,'Data ownership and privacy matter.','original'),
('127.59.d.3.F',4,'Before using a public map layer, a student should check:','["Nothing", "Only the color", "Only the file size", "The source and date of the data"]'::jsonb,3,'Source quality affects reliability.','original'),
('127.59.d.4.A',3,'Which is hardware used with agricultural GIS?','["A GPS receiver on a tractor", "A cookbook", "A guitar", "A paint roller"]'::jsonb,0,'GPS hardware records positions.','original'),
('127.59.d.4.A',4,'Software used to view and analyze farm maps is called:','["A music player", "GIS software", "A game console", "Word art"]'::jsonb,1,'GIS software handles spatial data.','original'),
('127.59.d.4.B',3,'Spatial data storage means:','["Burning data", "Throwing data away", "Keeping map data in organized files or databases", "Hiding data"]'::jsonb,2,'Storage supports reuse.','original'),
('127.59.d.4.B',4,'Cleaning data before mapping helps to:','["Hide the maps", "Add mistakes", "Slow the work", "Remove errors that would give wrong results"]'::jsonb,3,'Quality control precedes analysis.','original'),
('127.59.d.4.C',3,'Satellite and drone images can reveal crop stress by:','["Showing differences in plant color and heat", "Opening gates", "Playing music", "Printing receipts"]'::jsonb,0,'Sensors read reflected light.','original'),
('127.59.d.4.C',4,'NDVI is a remote-sensing index used to estimate:','["Rainfall totals only", "Plant vigor", "Road traffic", "Fuel price"]'::jsonb,1,'NDVI compares red and near-infrared light.','original'),
('127.59.d.5.A',3,'Latitude and longitude form a:','["Recipe", "Price list", "Coordinate system for locating places", "Weather chart"]'::jsonb,2,'Coordinates give positions.','original'),
('127.59.d.5.A',4,'A map projection is used to:','["Make the earth flat", "Change the weather", "Remove oceans", "Show the curved earth on a flat map"]'::jsonb,3,'Projections flatten the globe with some distortion.','original'),
('127.59.d.5.B',3,'GPS-guided steering helps farmers by:','["Reducing overlap and skips in the field", "Making rows crooked", "Removing seed", "Increasing overlap"]'::jsonb,0,'Accurate positioning saves inputs.','original'),
('127.59.d.5.B',4,'Using satellite positioning to apply seed only where needed can:','["Stop yield", "Increase profit by lowering input costs", "Waste seed", "Raise cost always"]'::jsonb,1,'Precise placement improves returns.','original'),
('127.59.d.6.A',3,'When analyzing yield data across a field, the first step is usually to:','["Delete half", "Print it", "Check the data for errors and outliers", "Guess"]'::jsonb,2,'Clean data give reliable results.','original'),
('127.59.d.6.A',4,'Overlaying a soil map on a yield map helps to:','["Create random shapes", "Stop analysis", "Erase layers", "Find relationships between soil and yield"]'::jsonb,3,'Overlay shows patterns across layers.','original'),
('127.59.d.6.B',3,'Precision refers to how:','["Close repeated measurements are to each other", "Old a map is", "Big a map is", "Colorful a map is"]'::jsonb,0,'Precision is repeatability.','original'),
('127.59.d.6.B',4,'Accuracy refers to how:','["Large the file is", "Close a measurement is to the true value", "Many layers there are", "Old the satellite is"]'::jsonb,1,'Accuracy is closeness to truth.','original'),
('127.59.d.7.A',3,'A GIS map shows a wet low spot in a field. The variable affecting crops there is likely:','["Fence color", "Road name", "Drainage", "Mailbox"]'::jsonb,2,'Wet areas affect root health.','original'),
('127.59.d.7.A',4,'A map shows low yield in a sandy zone. A variable to investigate is:','["Sunset time", "Brand of tractor", "School colors", "Soil water-holding capacity"]'::jsonb,3,'Sandy soil holds less water.','original'),
('127.59.d.7.B',3,'Raster data store information in a:','["Grid of cells", "List of names", "Text file only", "Single point"]'::jsonb,0,'Rasters are made of pixels.','original'),
('127.59.d.7.B',4,'Property boundaries are best stored as:','["Sound files", "Vector polygons", "Text notes", "Raster cells only"]'::jsonb,1,'Polygons have sharp edges.','original'),
('127.59.d.7.C',3,'A buffer analysis in natural resource work could find:','["The weather forecast", "The tallest tree", "Land within a set distance of a stream", "The price of corn"]'::jsonb,2,'Buffers create zones around features.','original'),
('127.59.d.7.C',4,'Mapping wildlife habitat and pasture together helps managers to:','["Stop mapping", "Ignore wildlife", "Remove all cattle", "Plan grazing that protects habitat"]'::jsonb,3,'Overlay supports land management.','original'),
('127.59.d.8.A',3,'A map that shows how soil types vary across a field is a:','["Soil map", "Road map only", "Star chart", "Menu"]'::jsonb,0,'Thematic maps show a single theme.','original'),
('127.59.d.8.A',4,'A map showing crop vigor from a drone is a(n):','["Phone book", "Remote-sensing image map", "Cookbook", "Calendar"]'::jsonb,1,'It displays sensor data spatially.','original'),
('127.59.d.8.B',3,'To make a map of fertilizer rates, a student would:','["Skip data", "Draw by hand only", "Add the data to GIS and assign colors by rate", "Print a blank page"]'::jsonb,2,'GIS symbolizes data values.','original'),
('127.59.d.8.B',4,'A good map includes a title, legend, and:','["A phone number", "A joke", "A recipe", "Scale and north arrow"]'::jsonb,3,'Map elements help readers.','original'),
('127.59.d.8.C',3,'A legend on a farm map explains:','["What the colors and symbols mean", "The weather", "Who owns the tractor", "The price of seed"]'::jsonb,0,'The legend decodes symbols.','original'),
('127.59.d.8.C',4,'Using red for ''low'' and green for ''high'' yield is an example of:','["A weather alert", "Cartographic symbols", "A printing error", "Random decoration"]'::jsonb,1,'Symbols communicate values.','original'),
('127.59.d.8.D',3,'A manager sees a map with low nitrogen in one zone. The decision supported is:','["Where to build a house", "What to cook", "Where to apply extra fertilizer", "What song to play"]'::jsonb,2,'Visual data guide inputs.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
