select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_11_v1'
from (values
('127.59.d.8.D',4,'Visual data from GIS help farm managers to:','["Reduce information", "Increase guesswork", "Avoid decisions", "Make decisions that save money and improve yield"]'::jsonb,3,'Maps turn data into action.','original'),
('127.61.d.1.A',3,'A student managing two hives as a school project and recording results is doing a:','["Supervised agricultural experience in beekeeping", "Pep rally", "Field trip only", "Lunch club"]'::jsonb,0,'An SAE is a planned, supervised project.','original'),
('127.61.d.1.A',4,'The final step of a beekeeping SAE is to:','["Sell the hive tools", "Evaluate what the project taught and how to improve", "Ignore the hives", "Hide the records"]'::jsonb,1,'Evaluation closes the cycle.','original'),
('127.61.d.1.B',2,'Why note the date and condition of a hive at each inspection?','["To scare bees", "To waste paper", "To track colony health over time", "To hide data"]'::jsonb,2,'Inspection logs reveal trends.','original'),
('127.61.d.1.B',3,'A good apiary record includes:','["Only the weather channel", "Sports scores", "Nothing", "Queen status, brood pattern, and honey stores"]'::jsonb,3,'Hive records guide management.','original'),
('127.61.d.1.C',2,'Which builds leadership in a beekeeping program?','["Teaching younger members about hive safety", "Staying silent", "Avoiding responsibility", "Skipping events"]'::jsonb,0,'Teaching others builds leadership.','original'),
('127.61.d.1.D',2,'A chapter program of activities for beekeeping could include:','["Cancelled events", "A honey tasting fundraiser", "No meetings", "Hidden plans"]'::jsonb,1,'The program lists planned events.','original'),
('127.61.d.1.D',3,'A student who helps with the honey tasting fundraiser is:','["Breaking rules", "Dropping out", "Participating in the local program of activities", "Avoiding service"]'::jsonb,2,'Taking part supports the chapter.','original'),
('127.61.d.1.E',3,'A résumé entry such as ''maintained four hives for two seasons'' is:','["A schedule", "A lab rule", "A weather report", "Documentation of agricultural experience"]'::jsonb,3,'It records real experience.','original'),
('127.61.d.1.E',2,'Documentation of beekeeping experience helps with:','["Applications for jobs and scholarships", "Losing awards", "Skipping school", "Hiding skills"]'::jsonb,0,'Updated records show ability.','original'),
('127.61.d.2.A',3,'A honeybee that lives only a few weeks in summer is usually a:','["Drone in winter", "Worker", "Queen", "Egg"]'::jsonb,1,'Summer workers live about 5 to 6 weeks.','original'),
('127.61.d.2.A',4,'Which bee typically lives the longest, sometimes for years?','["The worker", "The larva", "The queen", "The drone"]'::jsonb,2,'Queens can live several years.','original'),
('127.61.d.2.B',3,'The main job of the queen is to:','["Collect nectar", "Make wax", "Guard the entrance", "Lay eggs"]'::jsonb,3,'A queen lays up to 1,500 eggs a day.','original'),
('127.61.d.2.B',4,'Drones exist mainly to:','["Mate with queens", "Build comb", "Feed larvae", "Gather pollen"]'::jsonb,0,'Drones are male bees.','original'),
('127.61.d.2.C',3,'Honeybee development goes through egg, larva, pupa, and then:','["Root", "Adult", "Seed", "Leaf"]'::jsonb,1,'This is complete metamorphosis.','original'),
('127.61.d.2.C',4,'Division of labor in a hive means:','["The queen does everything", "Bees never change tasks", "Bees perform different jobs as they age", "All bees do one job"]'::jsonb,2,'Workers progress from nurse to forager.','original'),
('127.61.d.3.A',3,'A good apiary site has:','["No flowers nearby", "Deep shade all day", "Standing flood water", "Morning sun, wind protection, and nearby water"]'::jsonb,3,'Site traits affect colony health.','original'),
('127.61.d.3.A',4,'Placing hives where the entrance faces east helps because it:','["Warms the hive early so bees start foraging sooner", "Floods the hive", "Attracts predators", "Blocks all sun"]'::jsonb,0,'Morning sun speeds activity.','original'),
('127.61.d.3.B',3,'A nectar flow is the period when:','["Bees sleep", "Many plants produce nectar bees can collect", "Hives are moved", "Flowers are absent"]'::jsonb,1,'Flow timing affects honey production.','original'),
('127.61.d.3.B',4,'An area with few flowering plants will likely support:','["Faster growth", "No change", "Fewer or weaker colonies", "More honey"]'::jsonb,2,'Forage limits colony size.','original'),
('127.61.d.3.C',3,'Comparing beehives in other regions helps a beekeeper to:','["Copy blindly", "Skip planning", "Ignore climate", "Learn practices that suit similar conditions"]'::jsonb,3,'Comparisons guide management.','original'),
('127.61.d.3.C',4,'A beekeeper in Texas might study hives in Florida because:','["The warm climates share management challenges", "Climate is irrelevant", "Texas has no bees", "Florida has snow"]'::jsonb,0,'Similar climates mean similar issues.','original'),
('127.61.d.3.D',3,'A hive installation plan should consider:','["Movie times", "Hive spacing, stands, and safe access", "Pizza toppings", "Shoe sizes"]'::jsonb,1,'Layout affects safety and efficiency.','original'),
('127.61.d.3.D',4,'Placing a hive on a stand helps by:','["Attracting skunks", "Increasing moisture", "Keeping it off damp ground and away from pests", "Blocking light"]'::jsonb,2,'Stands protect the equipment.','original'),
('127.61.d.4.A',3,'Bees adapt to cold weather by:','["Sleeping alone", "Flying south", "Leaving the hive", "Clustering to keep the queen warm"]'::jsonb,3,'Winter clusters generate heat.','original'),
('127.61.d.4.A',4,'In a heat wave, bees cool the hive by:','["Fanning wings and bringing in water", "Clustering tightly", "Closing every vent", "Making honey faster"]'::jsonb,0,'Evaporation cools the colony.','original'),
('127.61.d.4.B',3,'In spring, a beekeeper often watches for:','["Winter clustering only", "Colony growth and swarm preparation", "Snow", "Honey harvest only"]'::jsonb,1,'Spring brings rapid expansion.','original'),
('127.61.d.4.B',4,'Adding extra boxes in the nectar flow helps because it:','["Removes bees", "Blocks the entrance", "Gives the colony room to store honey and reduces swarming", "Lowers honey"]'::jsonb,2,'Space management prevents crowding.','original'),
('127.61.d.4.C',3,'Winterizing a hive often includes:','["Opening all vents", "Moving it into shade", "Removing all honey", "Reducing the entrance and making sure stores are adequate"]'::jsonb,3,'Winter prep protects the colony.','original'),
('127.61.d.4.C',4,'Providing wind protection in winter helps bees to:','["Conserve heat and energy", "Lose heat", "Starve faster", "Overheat"]'::jsonb,0,'Wind increases heat loss.','original'),
('127.61.d.5.A',3,'A hive tool is used to:','["Dig soil", "Pry apart hive boxes and frames", "Cut grass", "Pour honey"]'::jsonb,1,'The hive tool loosens propolis.','original'),
('127.61.d.5.A',4,'A smoker is used to:','["Melt wax", "Mark frames", "Calm bees before opening the hive", "Cook food"]'::jsonb,2,'Smoke masks alarm pheromones.','original'),
('127.61.d.5.B',3,'During an inspection, a beekeeper checks the:','["Radio signal", "Neighbor''s yard", "Color of the stand", "Brood pattern and presence of the queen or eggs"]'::jsonb,3,'Eggs show a queen is present.','original'),
('127.61.d.5.B',4,'Equipment commonly needed for an inspection includes:','["A veil, smoker, and hive tool", "Fishing pole", "Rake and hoe", "Tennis racket"]'::jsonb,0,'Basic tools protect and assist.','original'),
('127.61.d.5.C',3,'A healthy brood pattern is:','["Moldy", "Solid and compact", "Empty", "Scattered and spotty"]'::jsonb,1,'Solid patterns show a strong queen.','original'),
('127.61.d.5.C',4,'A spotty brood pattern may indicate:','["Perfect health", "A new stand", "A failing queen or disease", "Too much honey"]'::jsonb,2,'Gaps can signal problems.','original'),
('127.61.d.5.D',3,'A safety precaution when working bees is:','["Ignore allergies", "Open hives in the storm", "Work barefoot", "Wear a veil and know how to react to a sting"]'::jsonb,3,'Preparation prevents harm.','original'),
('127.61.d.5.D',4,'A person with a known severe sting allergy should:','["Have an emergency plan and medication available", "Skip safety gear", "Work alone without help", "Ignore the risk"]'::jsonb,0,'Allergic reactions can be life threatening.','original'),
('127.61.d.5.E',3,'Moving slowly and calmly around hives helps to:','["Make bees angry", "Avoid alarming the bees", "Spread disease", "Lose frames"]'::jsonb,1,'Sudden motion triggers defense.','original'),
('127.61.d.5.E',4,'Handling frames gently protects:','["Only the beekeeper", "Only the wood", "Both the bees and the queen", "Only the wax"]'::jsonb,2,'Crushing bees releases alarm scent.','original'),
('127.61.d.5.F',3,'Protective clothing for beekeeping includes:','["Roller skates", "Sandals only", "Swim trunks", "A veil, gloves, and a bee suit"]'::jsonb,3,'PPE reduces stings.','original'),
('127.61.d.5.F',4,'Light-colored clothing is preferred because dark colors:','["May look like predators to bees", "Cool bees", "Attract flowers", "Repel wax moths"]'::jsonb,0,'Bees defend against dark animals.','original'),
('127.61.d.6.A',3,'The varroa mite is a pest that:','["Cleans hives", "Feeds on bees and spreads viruses", "Pollinates", "Makes honey"]'::jsonb,1,'Varroa is a major threat.','original'),
('127.61.d.6.A',4,'American foulbrood is caused by:','["A fungus on flowers", "A rain cloud", "A bacterium that kills larvae", "An insect only"]'::jsonb,2,'AFB is a serious brood disease.','original'),
('127.61.d.6.B',3,'A component of honeybee IPM is:','["Spraying monthly regardless", "Ignoring pests", "Removing the queen", "Monitoring mite levels"]'::jsonb,3,'Monitoring guides treatment.','original'),
('127.61.d.6.B',4,'Using screened bottom boards to reduce mites is a:','["Cultural or mechanical control", "Biological only", "Burning", "Chemical only"]'::jsonb,0,'Physical methods help.','original'),
('127.61.d.6.C',3,'Before applying a treatment in a hive, read the:','["Weather news", "Label and follow directions", "Sports page", "Radio"]'::jsonb,1,'The label is the law.','original'),
('127.61.d.6.C',4,'Pesticide use near hives should be:','["Applied over bloom", "Ignored", "Timed to avoid harming foraging bees", "Done at noon always"]'::jsonb,2,'Evening applications reduce exposure.','original'),
('127.61.d.7.A',3,'A tool used to separate honey from comb is a(n):','["Smoker", "Rake", "Veil", "Extractor"]'::jsonb,3,'Extractors spin out honey.','original'),
('127.61.d.7.A',4,'An uncapping knife is used to:','["Cut wax cappings from honey cells", "Stir honey", "Cool honey", "Weigh honey"]'::jsonb,0,'Uncapping opens cells for extraction.','original'),
('127.61.d.7.B',3,'A safe practice when using an uncapping knife is to:','["Cut toward your hand", "Cut away from your body", "Use it dull", "Use it in the dark"]'::jsonb,1,'Cutting away prevents injuries.','original'),
('127.61.d.7.B',4,'Wearing gloves and keeping the work area clean during harvest helps prevent:','["Wax", "Flow", "Cuts and contamination", "Honey"]'::jsonb,2,'Safety and sanitation go together.','original'),
('127.61.d.7.C',3,'Technology that improves honey production includes:','["Hand cranks only", "Horses", "Candles", "Hive scales and sensors"]'::jsonb,3,'Sensors track hive weight and temperature.','original'),
('127.61.d.7.C',4,'A hive scale helps a beekeeper to:','["See nectar flow and stores without opening the hive", "Count flowers", "Weigh bees individually", "Measure rain"]'::jsonb,0,'Weight changes show flow.','original'),
('127.61.d.7.D',3,'Honey is strained after extraction to remove:','["Pollen entirely", "Wax bits and debris", "Sugar", "Water"]'::jsonb,1,'Straining clears the honey.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
